   600	// second half of the mechanic: the merge clears the issues collision, but the
   601	// counter row is a both-changed conflict the standard settle never touches.
   602	func resolveChildCountersToHighWater(ctx context.Context, db DBConn, report *storage.RebaseReport) error {
   603		// Pull each conflicted parent AND the three sides of its counter value. The
   604		// working set (ours) alone is not enough: this runs before the conflict
   605		// auto-resolve, so a theirs-only high-water lives only in the conflict row, and
   606		// a side that deleted its highest child (or holds it as a session wisp) can
   607		// carry a last_child the live issue rows no longer show. Folding our/their/base
   608		// into the mark guarantees the counter only ever rises (#4796).
   609		rows, err := db.QueryContext(ctx, `
   610			SELECT COALESCE(our_parent_id, their_parent_id, base_parent_id),
   611			       COALESCE(our_last_child, 0), COALESCE(their_last_child, 0), COALESCE(base_last_child, 0)
   612			FROM dolt_conflicts_child_counters`)
   613		if err != nil {
   614			// No conflict on this table (or Dolt version without the system table):
   615			// nothing to resolve here.
   616			if strings.Contains(err.Error(), "dolt_conflicts_child_counters") {
   617				return nil
   618			}
   619			return fmt.Errorf("query child_counters conflicts: %w", err)
   620		}
   621		type counterConflict struct {
   622			parent           string
   623			our, their, base int
   624		}
   625		var conflicts []counterConflict
   626		for rows.Next() {
   627			var cc counterConflict
   628			if err := rows.Scan(&cc.parent, &cc.our, &cc.their, &cc.base); err != nil {
   629				_ = rows.Close()
   630				return fmt.Errorf("scan child_counters conflict: %w", err)
   631			}
   632			conflicts = append(conflicts, cc)
   633		}
   634		if err := rows.Close(); err != nil {
   635			return err
   636		}
   637		if err := rows.Err(); err != nil {
   638			return err
   639		}
   640		if len(conflicts) == 0 {
   641			return nil
