   643	
   644		for _, cc := range conflicts {
   645			// child_counters.parent_id carries an FK to issues(id) ON DELETE CASCADE, so
   646			// a counter row cannot exist without its parent. A theirs-only conflict row
   647			// whose parent this merge leaves deleted — our side deleted the parent, which
   648			// cascaded our counter row away, while theirs bumped it — must stay deleted.
   649			// Re-inserting it would violate the FK and abort the whole rebase, where the
   650			// earlier UPDATE-only form correctly matched no rows. The canonical bulk
   651			// create path guards the same hazard ("their auxiliary counter has no owner
   652			// and must not be inserted", issueops/create.go). Skipping leaves the row to
   653			// DOLT_CONFLICTS_RESOLVE('--ours') below, which keeps our deletion.
   654			var parentExists int
   655			switch err := db.QueryRowContext(ctx, "SELECT 1 FROM issues WHERE id = ?", cc.parent).Scan(&parentExists); {
   656			case err == sql.ErrNoRows:
   657				continue
   658			case err != nil:
   659				return fmt.Errorf("check child_counters conflict parent %s: %w", cc.parent, err)
   660			}
   661	
   662			trueMax, err := maxChildNumber(ctx, db, "", cc.parent)
   663			if err != nil {
   664				return err
   665			}
   666			hw := trueMax
   667			for _, v := range []int{cc.our, cc.their, cc.base} {
   668				if v > hw {
   669					hw = v
   670				}
   671			}
   672			// Upsert with GREATEST so the counter can only rise, never fall — and so a
   673			// theirs-only conflict row (with no working-set counter to UPDATE) still
   674			// lands. Mirrors the counter bump in renumberCollisions.
   675			if _, err := db.ExecContext(ctx, `
   676				INSERT INTO child_counters (parent_id, last_child) VALUES (?, ?)
   677				ON DUPLICATE KEY UPDATE last_child = GREATEST(last_child, VALUES(last_child))`,
   678				cc.parent, hw); err != nil {
   679				return fmt.Errorf("set child_counters high-water for %s: %w", cc.parent, err)
   680			}
   681			report.CountersSet[cc.parent] = hw
   682		}
