   684			return fmt.Errorf("resolve child_counters conflicts: %w", err)
   685		}
   686		if _, err := db.ExecContext(ctx, "CALL DOLT_ADD('child_counters')"); err != nil {
   687			return fmt.Errorf("stage resolved child_counters: %w", err)
   688		}
   689		return nil
   690	}
